"""Password registration and verification API.

New passwords are stored using the current OWASP-approved primary algorithm
(Argon2id). Existing stored hashes of older formats remain verifiable.
"""

from __future__ import annotations

from password_store import hash_new_password, verify_password


def register_password(password: str) -> str:
    """Return the string to store for a newly registered user's password."""
    return hash_new_password(password)


def check_login(password: str, stored: str) -> bool:
    """Verify a login attempt against any stored password hash format."""
    return verify_password(password, stored)

"""FIPS-mode password hashing using PBKDF2-HMAC only.

This module exposes a minimal API for the FIPS subsystem:
- fips_password_hash(password, digest): create a new PBKDF2-HMAC hash
- fips_verify(password, stored): verify any stored PBKDF2-HMAC hash

New hashes use the currently recommended OWASP PBKDF2-HMAC iteration counts
for the requested digest. Legacy stored PBKDF2 hashes remain verifiable.
"""

from __future__ import annotations

from pbkdf2_hasher import hash_pbkdf2, verify_pbkdf2


_ALLOWED_DIGESTS = {"sha1", "sha256", "sha512"}


def fips_password_hash(password: str, digest: str) -> str:
    """Return a new PBKDF2-HMAC password hash for the requested digest."""
    if digest not in _ALLOWED_DIGESTS:
        raise ValueError(f"unsupported digest: {digest}")
    return hash_pbkdf2(password, digest)


def fips_verify(password: str, stored: str) -> bool:
    """Verify a password against a stored PBKDF2-HMAC hash."""
    return verify_pbkdf2(password, stored)

